<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php'; require dirname(__DIR__,2).'/vendor/autoload.php';
use App\Auth; use App\Security;
$user=Auth::requireUser(); $stats=['products'=>0,'categories'=>0,'orders'=>0,'new'=>0,'low'=>0];$canViewReports=(($user['role_name']??'')==='super_admin');$latest=[];
try{$pdo=db();if(!$canViewReports){$perm=$pdo->prepare("SELECT p.id FROM permissions p LEFT JOIN role_permissions rp ON rp.permission_id=p.id AND rp.role_id=? LEFT JOIN user_permissions up ON up.permission_id=p.id AND up.user_id=? WHERE p.permission_key='reports.view' AND (up.allowed=1 OR (up.allowed IS NULL AND rp.permission_id IS NOT NULL)) LIMIT 1");$perm->execute([(int)$user['role_id'],(int)$user['id']]);$canViewReports=(bool)$perm->fetchColumn();}if($canViewReports){$stats['products']=(int)$pdo->query("SELECT COUNT(*) FROM products")->fetchColumn();$stats['categories']=(int)$pdo->query("SELECT COUNT(*) FROM categories")->fetchColumn();$stats['orders']=(int)$pdo->query("SELECT COUNT(*) FROM orders")->fetchColumn();$stats['new']=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='new'")->fetchColumn();$stats['low']=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE stock_quantity-reserved_quantity<=low_stock_threshold")->fetchColumn();$latest=$pdo->query("SELECT order_number,status,total,created_at FROM orders ORDER BY id DESC LIMIT 8")->fetchAll();}}catch(Throwable $e){error_log($e->getMessage());$latest=[];$canViewReports=false;}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>لوحة التحكم | الفخامة</title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="../assets/css/store.css"><style>.admin{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.side{background:#101010;border-left:1px solid #49371c;padding:25px 18px}.side a{display:block;padding:11px;color:#ddd;border-radius:9px}.side a:hover{background:#292012;color:#f4c45e}.main{padding:30px}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.stat{padding:20px;border:1px solid #49371c;border-radius:14px;background:#141414}.stat b{display:block;font-size:27px;color:#f4c45e}.table{width:100%;border-collapse:collapse;margin-top:20px;background:#111}.table th,.table td{padding:12px;text-align:right;border-bottom:1px solid #302719;font-size:13px}@media(max-width:850px){.admin{grid-template-columns:1fr}.side{display:flex;overflow:auto;gap:5px;padding:10px}.side h3{display:none}.side a{white-space:nowrap}.stats{grid-template-columns:repeat(2,1fr)}.main{padding:18px}}</style></head><body><div class="admin"><aside class="side"><a class="brand" href="../"><span class="brand-mark">ف</span><span><strong>الفخامة</strong><small>ADMIN</small></span></a><h3>القائمة الرئيسية</h3><a href="index.php">نظرة عامة</a><a href="categories.php">الأقسام</a><a href="products.php">المنتجات</a><a href="orders.php">الطلبات</a><a href="inventory.php">المخزون</a><a href="users.php">المستخدمون والصلاحيات</a><a href="settings.php">إعدادات المتجر</a><a href="banners.php">صور الواجهة الرئيسية</a><a href="../">معاينة المتجر</a><form method="post" action="logout.php"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><button class="btn btn-outline" type="submit">تسجيل الخروج</button></form></aside><main class="main"><span class="eyebrow">لوحة الإدارة</span><h1>مرحباً، <?=e($user['name'])?></h1><?php if($canViewReports):?><div class="stats"><?php foreach(['products'=>'المنتجات','categories'=>'الأقسام','orders'=>'إجمالي الطلبات','new'=>'طلبات جديدة','low'=>'مخزون منخفض'] as $key=>$label):?><div class="stat"><span><?=e($label)?></span><b><?=number_format($stats[$key])?></b></div><?php endforeach;?></div><h2>أحدث الطلبات</h2><table class="table"><thead><tr><th>رقم الطلب</th><th>الحالة</th><th>الإجمالي</th><th>التاريخ</th></tr></thead><tbody><?php foreach($latest as $order):?><tr><td><?=e($order['order_number'])?></td><td><?=e($order['status'])?></td><td><?=number_format((float)$order['total'],2)?> ر.س</td><td><?=e($order['created_at'])?></td></tr><?php endforeach;?><?php if(!$latest):?><tr><td colspan="4">لا توجد طلبات حتى الآن.</td></tr><?php endif;?></tbody></table><?php else:?><div class="notice">لا تملك صلاحية عرض إحصائيات وتقارير المتجر. يمكنك استخدام الأقسام المسموح بها من القائمة.</div><?php endif;?></main></div></body></html>